// Key-leak guard (src/net/secret-key-leak.js): a valid nsec is never signed, sealed or saved into a profile, and a
// profile that publishes one marks that key's account public and outside the web. Every key here is generated by the
// test; none is ever sent anywhere.
import test from "node:test"
import assert from "node:assert/strict"
import { generateSecretKey, getPublicKey, finalizeEvent } from "nostr-tools/pure"
import { nsecEncode } from "nostr-tools/nip19"
import { bech32 } from "@scure/base"
import {
  SECRET_KEY_BLOCKED, PUBLIC_KEY_LABEL, containsSecretKey, derivedPubkeys, eventHasSecretKey, assertNoSecretKey,
  isPublicKeyAccount, notePublicKeys, onPublicKeys, forgetPublicKeys, holdsSecretKey,
} from "../src/net/secret-key-leak.js"
import { localSession, localSigner } from "../src/signer/local.js"
import { extensionSigner, forgetAccountCheck } from "../src/signer/nip07.js"
import { sendMessage, wrapFor, rumorFor } from "../src/net/dms.js"
import { isInbox } from "../src/net/dm-trust.js"
import { putProfile } from "../src/net/profiles.js"
import { saveProfile, formFields, removedNotice, withoutSecretKeys } from "../src/net/profile-edit.js"
import { gateWeb, judge, VERDICTS } from "../src/net/web-gate.js"
import { insideWeb } from "../src/net/web-trust.js"

const fresh = () => { const sk = generateSecretKey(); return { sk, pk: getPublicKey(sk), nsec: nsecEncode(sk) } }
/** The nsec with its last checksum character changed: same shape, bad checksum. */
const badChecksum = nsec => nsec.slice(0, -1) + (nsec.at(-1) === "q" ? "p" : "q")
const memKeys = () => { const m = new Map(); return { get: async n => m.get(n), add: async (n, k) => { if (m.has(n)) throw new Error("exists"); m.set(n, k) } } }

test("a valid nsec is found anywhere in the text, in either case and as nostr:nsec1…", () => {
  const k = fresh()
  assert.equal(containsSecretKey(k.nsec), true)
  assert.equal(containsSecretKey(`my name is ${k.nsec}, hi`), true)
  assert.equal(containsSecretKey(`nostr:${k.nsec}`), true)
  assert.equal(containsSecretKey(k.nsec.toUpperCase()), true)
  assert.deepEqual(derivedPubkeys(`name ${k.nsec} and again nostr:${k.nsec}`), [k.pk])
  const two = fresh()
  assert.deepEqual(derivedPubkeys(`${k.nsec} ${two.nsec}`).sort(), [k.pk, two.pk].sort())
})

test("only a checksum-valid 32-byte nsec counts: not the prefix, a cut-off key, a bad checksum or mixed case", () => {
  const k = fresh()
  assert.equal(containsSecretKey("nsec1"), false)
  assert.equal(containsSecretKey("paste your nsec1 here"), false)
  assert.equal(containsSecretKey(k.nsec.slice(0, 50)), false) // the truncated-nsec farm in the research note
  assert.equal(containsSecretKey(k.nsec.slice(0, -1)), false)
  assert.equal(containsSecretKey(badChecksum(k.nsec)), false)
  const mixed = k.nsec.slice(0, 10) + k.nsec.slice(10, 20).toUpperCase() + k.nsec.slice(20)
  assert.equal(containsSecretKey(mixed), false)
  // A checksum-valid "nsec" that isn't 32 bytes, and a valid npub / note, are not secret keys.
  assert.equal(containsSecretKey(bech32.encode("nsec", bech32.toWords(new Uint8Array(31).fill(7)))), false)
  assert.equal(containsSecretKey(bech32.encode("npub", bech32.toWords(generateSecretKey()))), false)
  assert.equal(containsSecretKey("insecure Fonseca intensecasino"), false)
  assert.deepEqual(derivedPubkeys(badChecksum(k.nsec)), [])
})

test("an event carries a key in its content or any tag value", () => {
  const k = fresh()
  assert.equal(eventHasSecretKey({ kind: 1, content: "hello", tags: [["t", "nostr"]] }), false)
  assert.equal(eventHasSecretKey({ kind: 1, content: `hi ${k.nsec}`, tags: [] }), true)
  assert.equal(eventHasSecretKey({ kind: 1, content: "hi", tags: [["subject", k.nsec]] }), true)
  assert.equal(eventHasSecretKey({ kind: 0, content: JSON.stringify({ name: k.nsec }), tags: [] }), true)
  assert.throws(() => assertNoSecretKey({ kind: 30023, content: `# Title\n${k.nsec}`, tags: [] }), e => e.message === SECRET_KEY_BLOCKED && e.fixed)
})

test("the browser's own key signer refuses a note, a profile and an article with a key in them", async () => {
  const me = fresh(), leaked = fresh()
  const ks = memKeys()
  const signer = localSigner(await localSession(me.sk, "correct horse", { keyStore: ks, logn: 4 }), { keyStore: ks })
  for (const t of [
    { kind: 1, created_at: 1, tags: [], content: `my key ${leaked.nsec}` },
    { kind: 1111, created_at: 1, tags: [["K", "1"]], content: me.nsec },
    { kind: 0, created_at: 1, tags: [], content: JSON.stringify({ name: leaked.nsec }) },
    { kind: 30023, created_at: 1, tags: [["d", "a"], ["summary", leaked.nsec]], content: "body" },
  ]) await assert.rejects(signer.signEvent(t), e => e.message === SECRET_KEY_BLOCKED)
  const ok = await signer.signEvent({ kind: 1, created_at: 1, tags: [], content: "just words" })
  assert.equal(ok.pubkey, me.pk)
})

test("an extension never sees an event with a key in it", async t => {
  const me = fresh(), leaked = fresh()
  let asked = 0
  globalThis.nostr = { getPublicKey: async () => me.pk, signEvent: async ev => { asked++; return finalizeEvent(ev, me.sk) } }
  t.after(() => { delete globalThis.nostr; forgetAccountCheck() })
  const signer = extensionSigner(me.pk)
  await assert.rejects(signer.signEvent({ kind: 1, created_at: 1, tags: [], content: leaked.nsec }), e => e.message === SECRET_KEY_BLOCKED)
  assert.equal(asked, 0)
  await signer.signEvent({ kind: 1, created_at: 1, tags: [], content: "fine" })
  assert.equal(asked, 1)
})

test("a message with a key is refused before it is sealed, shown or sent", async () => {
  const me = fresh(), peer = fresh(), leaked = fresh()
  let encrypted = 0, published = 0
  const crypto = { encrypt: async () => { encrypted++; return "x" }, decrypt: async () => "" }
  const ctx = { vault: {}, session: { method: "nip07", pubkey: me.pk }, signer: { signEvent: async ev => finalizeEvent(ev, me.sk) }, account: { relays: { read: [], write: ["wss://w.example"] } } }
  await assert.rejects(sendMessage(ctx, peer.pk, `here ${leaked.nsec}`, { crypto, query: async () => [], publish: urls => { published++; return urls.map(() => Promise.resolve("")) } }),
    e => e.message === SECRET_KEY_BLOCKED && e.fixed)
  assert.equal(encrypted, 0)
  assert.equal(published, 0)
  // The seal path checks too, for any caller that skips sendMessage.
  await assert.rejects(wrapFor(rumorFor(me.pk, peer.pk, leaked.nsec), { signer: ctx.signer, crypto, me: me.pk }, peer.pk), e => e.message === SECRET_KEY_BLOCKED)
  assert.equal(encrypted, 0)
})

test("Edit Profile refuses a key typed into any field before it looks anything up", async () => {
  const me = fresh(), leaked = fresh()
  let looked = 0, signed = 0
  const ctx = { session: { pubkey: me.pk }, account: { relays: { read: [], write: [] } }, signer: { signEvent: async t => { signed++; return finalizeEvent(t, me.sk) } } }
  await assert.rejects(saveProfile(ctx, formFields(), { ...formFields(), about: `backup: ${leaked.nsec}` }, { lookup: async () => { looked++; return {} }, publish: () => [] }),
    e => e.message === SECRET_KEY_BLOCKED)
  assert.equal(looked, 0)
  assert.equal(signed, 0)
})

test("a loaded profile with a key marks that key's account public; the gate keeps it outside", () => {
  forgetPublicKeys()
  const victim = fresh(), throwaway = fresh(), friend = fresh(), me = fresh()
  const heard = []
  const off = onPublicKeys(pks => heard.push(...pks))
  assert.equal(isPublicKeyAccount(victim.pk), false)
  // The throwaway's profile has the victim's nsec as its name (the common case in the research note).
  putProfile(finalizeEvent({ kind: 0, created_at: 100, tags: [], content: JSON.stringify({ name: victim.nsec }) }, throwaway.sk))
  off()
  assert.equal(isPublicKeyAccount(victim.pk), true)
  assert.equal(isPublicKeyAccount(victim.pk.toUpperCase()), true)
  assert.equal(isPublicKeyAccount(throwaway.pk), false)
  assert.deepEqual(heard, [victim.pk])
  // Seeing it again tells no one twice.
  assert.deepEqual(notePublicKeys({ kind: 0, content: JSON.stringify({ about: victim.nsec }), tags: [] }), [])
  // Not kind 0: nothing is marked.
  assert.deepEqual(notePublicKeys({ kind: 1, content: friend.nsec, tags: [] }), [])

  // Followed and whitelisted, it is still outside; your own account and a surface's `always` key are not.
  const web = gateWeb({ own: [me.pk], whitelist: [victim.pk], web: [victim.pk, friend.pk] })
  assert.equal(judge({ signer: victim.pk, related: [], muted: [], refs: [] }, web), VERDICTS.outside)
  assert.equal(judge({ signer: victim.pk, related: [], muted: [], refs: [] }, web, { reach: "everyone" }), VERDICTS.outside)
  assert.equal(judge({ signer: friend.pk, related: [], muted: [], refs: [] }, web), VERDICTS.inside)
  assert.equal(judge({ signer: victim.pk, related: [], muted: [], refs: [] }, web, { always: [victim.pk] }), VERDICTS.inside)
  const ownWeb = gateWeb({ own: [victim.pk], web: [] })
  assert.equal(judge({ signer: victim.pk, related: [], muted: [], refs: [] }, ownWeb), VERDICTS.inside)
  // Blocked stays blocked.
  const blocked = gateWeb({ web: [victim.pk], blocked: new Set([victim.pk]) })
  assert.equal(judge({ signer: victim.pk, related: [], muted: [], refs: [] }, blocked), VERDICTS.blocked)
  // The reply/chat web and the Messages inbox.
  assert.equal(insideWeb(victim.pk, new Set([victim.pk])), false)
  assert.equal(insideWeb(friend.pk, new Set([friend.pk])), true)
  assert.equal(isInbox(victim.pk, false, new Set([victim.pk]), new Set([me.pk])), false)
  assert.equal(isInbox(victim.pk, true, new Set(), new Set([me.pk])), true) // you wrote in it
  assert.ok(PUBLIC_KEY_LABEL.startsWith("Key is public"))
  forgetPublicKeys()
})

test("the zero key and the curve order derive no pubkey", () => {
  const n = Uint8Array.from(Buffer.from("fffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141", "hex"))
  for (const bytes of [new Uint8Array(32), n]) {
    const nsec = bech32.encode("nsec", bech32.toWords(bytes))
    assert.equal(containsSecretKey(nsec), true) // still never published
    assert.deepEqual(derivedPubkeys(nsec), [])
    assert.deepEqual(notePublicKeys({ kind: 0, content: JSON.stringify({ name: nsec }), tags: [] }), [])
  }
})

test("a repost carries someone else's note as it is: the signer lets kinds 6 and 16 through", async () => {
  const me = fresh(), leaked = fresh()
  const inner = finalizeEvent({ kind: 1, created_at: 1, tags: [], content: `oops ${leaked.nsec}` }, leaked.sk)
  assert.doesNotThrow(() => assertNoSecretKey({ kind: 6, content: JSON.stringify(inner), tags: [["e", inner.id], ["p", inner.pubkey]] }))
  assert.doesNotThrow(() => assertNoSecretKey({ kind: 16, content: JSON.stringify(inner), tags: [["k", "1"]] }))
  const ks = memKeys()
  const signer = localSigner(await localSession(me.sk, "correct horse", { keyStore: ks, logn: 4 }), { keyStore: ks })
  assert.equal((await signer.signEvent({ kind: 6, created_at: 1, tags: [], content: JSON.stringify(inner) })).kind, 6)
  // A quote is your own note: still refused.
  await assert.rejects(signer.signEvent({ kind: 1, created_at: 1, tags: [["q", inner.id]], content: `look nostr:${leaked.nsec}` }), e => e.message === SECRET_KEY_BLOCKED)
})

test("the setup name box: a key with its checksum cut off (60 characters) still counts there", () => {
  const k = fresh()
  assert.equal(holdsSecretKey(k.nsec.slice(0, 60)), true)
  assert.equal(containsSecretKey(k.nsec.slice(0, 60)), false) // everywhere else only a whole, valid key counts
  assert.equal(holdsSecretKey(k.nsec.slice(0, 50)), false)
  assert.equal(holdsSecretKey("Satoshi"), false)
  assert.equal(holdsSecretKey(k.nsec), true)
})

test("Edit Profile leaves out a key hidden in a field or tag the form doesn't show, and says where", async () => {
  const me = fresh(), leaked = fresh()
  const prev = finalizeEvent({ kind: 0, created_at: 100, tags: [["i", "github:x", "proof"], ["note", leaked.nsec]],
    content: JSON.stringify({ name: "sat", displayName: leaked.nsec, lud06: "lnurl1x" }) }, me.sk)
  const signed = []
  const ctx = { session: { pubkey: me.pk }, account: { relays: { read: [], write: ["wss://w.example"] } }, vault: { outbox: { event: async () => ({ ok: true }) } },
    signer: { signEvent: async t => { assertNoSecretKey(t); const ev = finalizeEvent(t, me.sk); signed.push(ev); return ev } } }
  const initial = formFields(prev)
  const out = await saveProfile(ctx, initial, { ...initial, about: "hello" }, { lookup: async () => ({ event: prev, netFound: true, asked: 1, answered: 1 }), publish: urls => urls.map(() => Promise.resolve("")) })
  assert.equal(signed.length, 1)
  const c = JSON.parse(signed[0].content)
  assert.deepEqual(c, { name: "sat", lud06: "lnurl1x", about: "hello" })
  assert.deepEqual(signed[0].tags, [["i", "github:x", "proof"]])
  assert.deepEqual(out.removed, ["displayName", "the note tag"])
  const notice = removedNotice(out.removed)
  assert.equal(notice, "Removed a secret key from displayName, the note tag.")
  assert.equal(notice.includes(leaked.nsec), false)
  assert.equal(removedNotice([]), "")
  const clean = withoutSecretKeys({ name: "a", about: "b" }, [["t", "x"]])
  assert.deepEqual(clean, { profile: { name: "a", about: "b" }, tags: [["t", "x"]], removed: [] })
})
